+     * @param prefix A prefix for each chunk, which should be reasonably unique to allow for reconstruction of the original message even if
+     *               multiple such streams are used concurrently.
+     */
+    public static OutputStream create(Logger logger, Level level, String prefix) throws IOException {
+        return new GZIPOutputStream(Base64.getEncoder().wrap(new ChunkedLoggingStream(logger, level, prefix)));
+    }
+
+    private final Logger logger;
+    private final Level level;
+    private final String prefix;
+
+    private int chunk;
+    private int offset;
+    private boolean closed;
+    private final byte[] buffer = new byte[CHUNK_SIZE];
+
+    ChunkedLoggingStream(Logger logger, Level level, String prefix) {
+        this.logger = logger;
+        this.level = level;
+        this.prefix = prefix;
+    }
+
+    private void flushBuffer() {
+        assert closed || offset == CHUNK_SIZE : offset;
+        assert offset >= 0 && offset <= CHUNK_SIZE : offset;
+        chunk += 1;
+
+        final var chunkString = new String(buffer, 0, offset, StandardCharsets.ISO_8859_1);
+        offset = 0;
+
+        if (closed && chunk == 1) {
+            logger.log(level, "{} (gzip compressed and base64-encoded): {}", prefix, chunkString);
+        } else {
+            logger.log(level, "{} [part {}]: {}", prefix, chunk, chunkString);
+        }
+    }
+
+    @Override
+    public void write(int b) throws IOException {
+        assert closed == false;
+        if (offset == CHUNK_SIZE) {
+            flushBuffer();
+        }
+        buffer[offset] = (byte) b;
+        assert assertSafeByte(buffer[offset]);
+        offset += 1;
+    }
+
+    @Override
+    public void write(byte[] b, int off, int len) throws IOException {
+        assert closed == false;
+        assert assertSafeBytes(b, off, len);
+        while (len > 0) {
+            if (offset == CHUNK_SIZE) {
+                flushBuffer();
+            }
+            var copyLen = Math.min(len, CHUNK_SIZE - offset);
+            System.arraycopy(b, off, buffer, offset, copyLen);
+            offset += copyLen;
+            off += copyLen;
+            len -= copyLen;
+        }
+    }
+
+    @Override
+    public void close() throws IOException {
+        if (closed == false) {
+            closed = true;
+            flushBuffer();
+            if (chunk > 1) {
+                logger.log(level, "{} (gzip compressed, base64-encoded, and split into {} parts on preceding log lines)", prefix, chunk);
+            }
+        }
+    }
+
+    private static boolean assertSafeBytes(byte[] b, int off, int len) {
+        for (int i = off; i < off + len; i++) {
+            assertSafeByte(b[i]);
+        }
+        return true;
+    }
+
+    private static boolean assertSafeByte(byte b) {
+        assert 0x20 <= b && b < 0x7f;
+        return true;
+    }
+}

